// =============================================================================
// rPLL wrapper generated by the Gowin IP tool; divider and phase settings
// edited for this design.
//
//   clkout   27 MHz * (FBDIV_SEL+1) / (IDIV_SEL+1) = 27 * 8 / 9 = 24 MHz
//   clkoutp  the same clock, phase shifted by PSDA_SEL, for the SDRAM
//
// fVCO = 24 MHz * ODIV_SEL = 768 MHz (range 400-1200). The phase-detector
// input is 27 / 9 = 3 MHz, the minimum this rPLL supports. 24 MHz divides to
// the 1 MHz CLINT timebase exactly. These settings are fixed for SOC_CLK_HZ =
// 24000000; the top level rejects any other value.
// =============================================================================

module Gowin_rPLL (clkout, clkoutp, lock, reset, clkin);

output clkout;
output clkoutp;
output lock;
input reset;
input clkin;

wire clkoutp_o;
wire clkoutd_o;
wire clkoutd3_o;
wire gw_gnd;

assign gw_gnd = 1'b0;

rPLL rpll_inst (
    .CLKOUT(clkout),
    .LOCK(lock),
    .CLKOUTP(clkoutp),
    .CLKOUTD(clkoutd_o),
    .CLKOUTD3(clkoutd3_o),
    .RESET(reset),
    .RESET_P(gw_gnd),
    .CLKIN(clkin),
    .CLKFB(gw_gnd),
    .FBDSEL({gw_gnd,gw_gnd,gw_gnd,gw_gnd,gw_gnd,gw_gnd}),
    .IDSEL({gw_gnd,gw_gnd,gw_gnd,gw_gnd,gw_gnd,gw_gnd}),
    .ODSEL({gw_gnd,gw_gnd,gw_gnd,gw_gnd,gw_gnd,gw_gnd}),
    .PSDA({gw_gnd,gw_gnd,gw_gnd,gw_gnd}),
    .DUTYDA({gw_gnd,gw_gnd,gw_gnd,gw_gnd}),
    .FDLY({gw_gnd,gw_gnd,gw_gnd,gw_gnd})
);

defparam rpll_inst.FBDIV_SEL = 7;
defparam rpll_inst.IDIV_SEL = 8;
defparam rpll_inst.ODIV_SEL = 32;

defparam rpll_inst.FCLKIN = "27";
defparam rpll_inst.DYN_IDIV_SEL = "false";
defparam rpll_inst.DYN_FBDIV_SEL = "false";
defparam rpll_inst.DYN_ODIV_SEL = "false";
// SDRAM clock phase: "1010" = 10/16 of a period = 225 degrees. The controller
// samples read data on clk, so this sets where in the SDRAM's output-valid
// window the sample falls. No tool checks it; the BIOS memory test does. If
// that fails after a clock change, try "1001" (202.5 deg) or "1000" (180 deg).
defparam rpll_inst.PSDA_SEL = "1010";
defparam rpll_inst.DYN_DA_EN = "false";
defparam rpll_inst.DUTYDA_SEL = "1000";
defparam rpll_inst.CLKOUT_FT_DIR = 1'b1;
defparam rpll_inst.CLKOUTP_FT_DIR = 1'b1;
defparam rpll_inst.CLKOUT_DLY_STEP = 0;
defparam rpll_inst.CLKOUTP_DLY_STEP = 0;
defparam rpll_inst.CLKFB_SEL = "internal";
defparam rpll_inst.CLKOUT_BYPASS = "false";
defparam rpll_inst.CLKOUTP_BYPASS = "false";
defparam rpll_inst.CLKOUTD_BYPASS = "false";
defparam rpll_inst.DYN_SDIV_SEL = 2;
defparam rpll_inst.CLKOUTD_SRC = "CLKOUT";
defparam rpll_inst.CLKOUTD3_SRC = "CLKOUT";
defparam rpll_inst.DEVICE = "GW2A-18C";

endmodule //Gowin_rPLL
